content.solution:
package consumer

import (
    "context"
    "fmt"
)

func (h Handler) Handle(ctx context.Context, event Event) error {
    return h.tx.WithTx(ctx, func(store Store) error {
        inserted, err := store.InsertInbox(ctx, event.ID)
        if err != nil { return fmt.Errorf("insert inbox: %w", err) }
        if !inserted { return nil }
        if err := store.Apply(ctx, event); err != nil { return fmt.Errorf("apply event %s: %w", event.ID, err) }
        return nil
    })
}
